#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/mise/tasks/placeholder.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Renders the prompt for tasks no stack has filled yet"
# MISE hide=true
# MISE tools={uv="latest", python="3.14"}

# Imported by each task that is a SLOT with no fill: a task whose name is part
# of the contract but whose mechanism depends on a stack that nobody has pinned.
#
# A placeholder ALWAYS exits 0. An unconfigured repo must still run
# `mise run code` and `mise run setup` from start to end: the docs that define
# a product are formatted, linted and gated from day one, and the slots with
# no fill tell the user about themselves instead of stopping the task that ran
# them.
#
# A task stops being a placeholder when it is OVERWRITTEN: the stack overlay
# ships its own file at the same path, with no marker. Nothing edits a
# placeholder in place.

import os

import helpers

# The marker of a placeholder task. dprint (the ruff plugin) writes the marker
# of a .py file with a space, so the search accepts both forms.
PLACEHOLDER_MARKER = "#PLACEHOLDER"
PLACEHOLDER_MARKERS = (b"#PLACEHOLDER", b"# PLACEHOLDER")


def placeholder_tasks():
  """Each task file of this repo that still has the marker, as a sorted list
  of task names. mise names the task of `70-x.py` `70-x`, so the names have no
  `.py`.

  `_scripts/` is excluded, because the libraries name the marker to search
  for it: without the exclusion the library reports itself as unconfigured.
  """
  root = f"{os.environ.get('MISE_PROJECT_ROOT', '')}/.config/mise/tasks"
  if not os.path.isdir(root):
    return []
  names = []
  for folder, dirs, files in os.walk(root):
    dirs[:] = [d for d in dirs if d != "_scripts"]
    for file in files:
      path = os.path.join(folder, file)
      if os.path.islink(path):
        continue
      try:
        with open(path, "rb") as f:
          data = f.read()
      except OSError:
        continue
      if not any(marker in data for marker in PLACEHOLDER_MARKERS):
        continue
      name = os.path.relpath(path, root).replace(os.sep, ":")
      names.append(name.removesuffix(".py"))
  return sorted(names)


def placeholder_notice(task, reason):
  """Print the reason, then the list for all the repo and the commands that
  resolve it. The list is for all the repo and not for the task: a user who
  finds one slot with no fill finds the others too, and one round of setup
  answers all of them. It always returns normally.
  """
  pending = " ".join(placeholder_tasks())

  helpers.print_warn(f"{task} is not configured yet — {reason}")
  helpers.print_newline()

  if pending.replace(" ", ""):
    helpers.print_yellow(f"Unconfigured in this repo: {pending}")
    helpers.print_newline()

  helpers.print_yellow("To configure them:")
  helpers.print_yellow("  /vwf:architecture   pin this repo's stack axes (do this first)")
  helpers.print_yellow("  /stackgen           materialize the packs that fill them")
  helpers.print_newline()
